"use strict";
(() => {
 const panel=document.createElement("section");panel.id="editor-panel";panel.hidden=true;
 panel.innerHTML=`<h1>Build your neighborhood</h1><p>Draw roads, shape junctions and place crossings. Stop traffic before editing.</p><details><summary>What rebuilding changes</summary><p>Creates a new scenario with straight road segments, circular zones and generated demand. Imported curves, turn restrictions and transit routes are not preserved. Original project files remain available. Review the rebuilt scenario before interpreting results.</p></details><label>City name<input id="city-name" maxlength="100"></label><div class="edit-tools" id="edit-tools"></div><p id="edit-hint" role="status"></p><div id="edit-properties"></div><label>Background vehicles / hour<input id="city-demand" type="number" min="0" max="10000" step="50"></label><div class="edit-tools"><button id="undo">Undo</button><button id="redo">Redo</button><button id="erase">Delete selected</button><button id="blank">New empty city</button></div><button class="primary" id="build-city">Build & simulate</button><div class="edit-tools"><button id="save-city">Save layout</button><button id="export-city">Export JSON</button><label class="import-label">Import JSON<input id="import-city" type="file" accept=".json"></label></div><label>Saved layouts<select id="saved-city"><option value="">Choose a layout</option></select></label><button id="load-city">Load selected</button><p>Road intersections connect when built. Grid: 10 m. Minimum road length: 8 m. Zone colors match the live view.</p>`;
 document.querySelector("aside").prepend(panel);
 let layout=null,tool="select",pick=null,anchor=null,moving=null,history=[],future=[],revision=0,busy=false;
 const clone=x=>JSON.parse(JSON.stringify(x)),id=p=>p+crypto.randomUUID().replaceAll("-","").slice(0,16),node=id=>layout.nodes.find(n=>n.id===id);
 const hints={select:"Click a road, crossing or zone to change its properties.",road:"Click two points to draw a road. Continue clicking to extend it. Escape ends the chain.",move:"Drag a junction to reshape connected roads.",zebra:"Click a road to add a zebra crossing. A new junction is inserted where needed.",signal:"Click a road to add a signalized crossing.",zone:"Click the map to place an activity zone.",pan:"Drag the map to pan. Scroll to zoom."};
 for(const [key,label] of Object.entries({select:"Select",road:"Draw road",move:"Move junction",zebra:"Zebra crossing",signal:"Signal crossing",zone:"Add zone",pan:"Pan"})){const b=document.createElement("button");b.textContent=label;b.dataset.tool=key;b.onclick=()=>{tool=key;anchor=null;refresh();};$("edit-tools").append(b);}
 function remember(){history.push(clone(layout));if(history.length>60)history.shift();future=[];}
 function refresh(){ $("project").textContent=layout.name;$("map-caption").textContent="Draft road layout · Build to run in SUMO with the selected seed";$("city-name").value=layout.name;$("city-demand").value=layout.traffic_per_hour;$("edit-hint").textContent=hints[tool];$("undo").disabled=!history.length;$("redo").disabled=!future.length;document.querySelectorAll("[data-tool]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.tool===tool)));properties();draw(); }
 function field(label,key,value,type="number",options=null){const l=document.createElement("label");l.textContent=label;const input=document.createElement(options?"select":"input");if(options)for(const v of options){const o=document.createElement("option");o.value=v;o.textContent=names[v]||v;input.append(o);}else input.type=type;input.value=value;if(type==="checkbox")input.checked=value;l.append(input);input.onchange=()=>{const collection=layout[pick.group],item=collection.find(x=>x.id===pick.id);remember();if(key==="type")item.parameters={};item[key]=type==="checkbox"?input.checked:type==="number"?Number(input.value):input.value;if(key==="signal")layout.crossings.filter(c=>c.node===item.id).forEach(c=>c.kind=item.signal?"signalized":"zebra");refresh();};$("edit-properties").append(l);}
 function properties(){const box=$("edit-properties");box.replaceChildren();const item=pick&&layout[pick.group].find(x=>x.id===pick.id);$("erase").disabled=!item;if(!item)return;const title=document.createElement("h2");title.textContent=pick.group==="roads"?"Road properties":pick.group==="zones"?"Zone properties":pick.group==="nodes"?"Junction properties":"Crossing properties";box.append(title);if(pick.group==="roads"){field("Lanes per direction (1–4)","lanes",item.lanes);field("Speed limit km/h (10–120)","speed",item.speed);field("Two-way road","two_way",item.two_way,"checkbox");}if(pick.group==="zones"){field("Activity","type",item.type,"text",Object.keys(names));field("Radius m (15–1000)","radius",item.radius);field("Population","population",item.population);}if(pick.group==="nodes"){field("X coordinate (m)","x",item.x);field("Y coordinate (m)","y",item.y);field("Traffic signal","signal",item.signal,"checkbox");}if(pick.group==="crossings")field("Walk time seconds (5–120)","walk_seconds",item.walk_seconds);}
 function nearest(p){return layout.nodes.find(n=>Math.hypot(n.x-p[0],n.y-p[1])<Math.max(8,12/view.scale));}
 function addNode(p){let n=nearest(p);if(!n){n={id:id("n"),x:Math.round(p[0]/10)*10,y:Math.round(p[1]/10)*10,signal:false};layout.nodes.push(n);}return n;}
 function roadAt(p){let best=null;for(const r of layout.roads){const a=node(r.a),b=node(r.b),dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p[0]-a.x)*dx+(p[1]-a.y)*dy)/(dx*dx+dy*dy))),q=[a.x+t*dx,a.y+t*dy],d=Math.hypot(p[0]-q[0],p[1]-q[1]);if(d<Math.max(10,14/view.scale)&&(!best||d<best.d))best={r,t,q,d};}return best;}
 function click(p){if(tool==="road"){const old=anchor&&node(anchor),near=nearest(p);if(old&&near?.id===old.id)return;remember();const n=addNode(p);if(old){if(Math.hypot(n.x-old.x,n.y-old.y)<8){layout=history.pop();return;}if(!layout.roads.some(r=>[r.a,r.b].includes(old.id)&&[r.a,r.b].includes(n.id)))layout.roads.push({id:id("r"),a:old.id,b:n.id,lanes:1,speed:40,two_way:true});}anchor=n.id;}
 else if(tool==="zone"){remember();const z={id:id("z"),type:"office",x:Math.round(p[0]/10)*10,y:Math.round(p[1]/10)*10,radius:70,population:200,parameters:{}};layout.zones.push(z);pick={group:"zones",id:z.id};}
 else if(tool==="zebra"||tool==="signal"){const hit=roadAt(p);if(!hit)return;remember();let n=nearest(hit.q);if(!n||![hit.r.a,hit.r.b].includes(n.id)){const a=node(hit.r.a),b=node(hit.r.b);if(Math.min(Math.hypot(hit.q[0]-a.x,hit.q[1]-a.y),Math.hypot(hit.q[0]-b.x,hit.q[1]-b.y))<8){layout=history.pop();return;}n={id:id("n"),x:hit.q[0],y:hit.q[1],signal:false};layout.nodes.push(n);const end=hit.r.b,newRoad={...hit.r,id:id("r"),a:n.id};hit.r.b=n.id;layout.roads.push(newRoad);layout.crossings.filter(c=>c.road===hit.r.id&&c.node===end).forEach(c=>c.road=newRoad.id);}
 n.signal=tool==="signal";layout.crossings.filter(c=>c.node===n.id).forEach(c=>c.kind=n.signal?"signalized":"zebra");if(!layout.crossings.some(c=>c.node===n.id&&c.road===hit.r.id))layout.crossings.push({id:id("c"),node:n.id,road:hit.r.id,kind:n.signal?"signalized":"zebra",walk_seconds:15});}
 else if(tool==="select"){const c=layout.crossings.find(c=>{const n=node(c.node);return Math.hypot(n.x-p[0],n.y-p[1])<12/view.scale;});const n=nearest(p),r=roadAt(p),z=[...layout.zones].reverse().find(z=>Math.hypot(z.x-p[0],z.y-p[1])<z.radius);pick=c?{group:"crossings",id:c.id}:n?{group:"nodes",id:n.id}:r?{group:"roads",id:r.r.id}:z?{group:"zones",id:z.id}:null;}refresh();}
 function render(){ctx.clearRect(0,0,size.w,size.h);ctx.fillStyle="#e6edf0";ctx.fillRect(0,0,size.w,size.h);ctx.fillStyle="#c3d2da";const step=50*view.scale;if(step>8)for(let x=(view.x%step+step)%step;x<size.w;x+=step)for(let y=(view.y%step+step)%step;y<size.h;y+=step)ctx.fillRect(x,y,2,2);
 for(const z of layout.zones){const p=project([z.x,z.y]),color=map.palette[z.type];ctx.beginPath();ctx.arc(...p,z.radius*view.scale,0,Math.PI*2);ctx.fillStyle=color+"28";ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=pick?.id===z.id?3:1;ctx.stroke();ctx.fillStyle=color;ctx.font="600 13px Segoe UI";ctx.fillText(names[z.type],p[0]+8,p[1]-18);}
 ctx.lineCap="round";for(const r of layout.roads){const a=node(r.a),b=node(r.b);path([[a.x,a.y],[b.x,b.y]]);ctx.strokeStyle=pick?.id===r.id?"#237ae0":"#61717b";ctx.lineWidth=Math.max(8,r.lanes*(r.two_way?2:1)*3.2*view.scale);ctx.stroke();ctx.setLineDash([8,8]);ctx.strokeStyle="#f7f0c2";ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([]);}
 for(const n of layout.nodes){const p=project([n.x,n.y]);ctx.beginPath();ctx.arc(...p,anchor===n.id?7:4,0,7);ctx.fillStyle=anchor===n.id?"#e58c24":"white";ctx.fill();ctx.strokeStyle="#47687b";ctx.lineWidth=1;ctx.stroke();}
 for(const c of layout.crossings){const n=node(c.node),r=layout.roads.find(r=>r.id===c.road),a=node(r.a),b=node(r.b),p=project([n.x,n.y]);ctx.save();ctx.translate(...p);ctx.rotate(-Math.atan2(b.y-a.y,b.x-a.x));const w=Math.max(14,r.lanes*(r.two_way?2:1)*3.2*view.scale);ctx.fillStyle="#354b59";ctx.fillRect(-6,-w/2,12,w);ctx.fillStyle="white";for(let y=-w/2;y<w/2;y+=4)ctx.fillRect(-5,y,10,2);if(c.kind==="signalized"){ctx.fillStyle="#d24453";ctx.beginPath();ctx.arc(9,-w/2,4,0,7);ctx.fill();}ctx.restore();}}
 async function request(action,extra={}){showError("");const r=await fetch("/api/control",{method:"POST",headers:{"Content-Type":"application/json","X-Simroad-Token":token},body:JSON.stringify({action,...extra})});const data=await r.json();if(!r.ok)throw Error(data.error);return data;}
 async function saved(){const list=await(await fetch("/api/layouts")).json();$("saved-city").replaceChildren(new Option("Choose a layout",""));for(const x of list)$("saved-city").add(new Option(x.name,x.id));}
 function mode(active){sceneEditor.active=active;panel.hidden=!active;for(const child of panel.parentElement.children)if(child!==panel)child.hidden=active;$("edit-city").textContent=active?"Return to live view":"Edit city";$("empty").hidden=active;update();draw();}
 const sceneEditor=window.sceneEditor={active:false,draw:render,update(){const active=["calibrating","building","starting","running","paused","stopping"].includes(state?.status);$("edit-city").disabled=active||!connected;$("build-city").disabled=active||busy;$("start").disabled ||= this.active;if(this.active){$("empty").hidden=true;panel.querySelectorAll("button,input,select").forEach(el=>el.disabled=busy||active);if(!busy&&!active){$("undo").disabled=!history.length;$("redo").disabled=!future.length;$("erase").disabled=!pick;}}},async sync(s){if(s.revision!==revision){map=await(await fetch("/api/map")).json();layout=await(await fetch("/api/editor")).json();setup();revision=s.revision;busy=false;mode(false);}if(s.status==="error")busy=false;}};
 $("edit-city").onclick=async()=>{try{if(sceneEditor.active){mode(false);return;}if(!layout){const r=await fetch("/api/editor"),data=await r.json();if(!r.ok)throw Error(data.error);layout=data;}mode(true);refresh();await saved();}catch(e){showError(e.message);}};
 $("city-name").onchange=()=>{remember();layout.name=$("city-name").value;};$("city-demand").onchange=()=>{remember();layout.traffic_per_hour=Number($("city-demand").value);};
 $("undo").onclick=()=>{if(history.length){future.push(clone(layout));layout=history.pop();pick=anchor=null;refresh();}};$("redo").onclick=()=>{if(future.length){history.push(clone(layout));layout=future.pop();pick=anchor=null;refresh();}};
 $("erase").onclick=()=>{if(!pick)return;remember();if(pick.group==="nodes"){const ids=layout.roads.filter(r=>[r.a,r.b].includes(pick.id)).map(r=>r.id);layout.roads=layout.roads.filter(r=>!ids.includes(r.id));layout.crossings=layout.crossings.filter(c=>c.node!==pick.id&&!ids.includes(c.road));}if(pick.group==="roads")layout.crossings=layout.crossings.filter(c=>c.road!==pick.id);layout[pick.group]=layout[pick.group].filter(x=>x.id!==pick.id);pick=null;refresh();};
 $("blank").onclick=()=>{remember();layout={version:1,name:"My neighborhood",nodes:[],roads:[],crossings:[],zones:[],traffic_per_hour:300};anchor=pick=null;refresh();};
 $("build-city").onclick=async()=>{try{busy=true;sceneEditor.update();await request("build",{layout,seed:Number($("seed").value),strategy:$("strategy").value});$("edit-hint").textContent="Building SUMO junctions, crossings and routes…";}catch(e){busy=false;showError(e.message);sceneEditor.update();}};
 $("save-city").onclick=async()=>{try{const result=await request("save_layout",{layout});await saved();$("saved-city").value=result.saved;$("edit-hint").textContent="Layout saved in simroad/scenes.";}catch(e){showError(e.message);}};
 $("load-city").onclick=async()=>{if(!$("saved-city").value)return;remember();layout=await(await fetch("/api/layout/"+$("saved-city").value)).json();pick=anchor=null;refresh();};
 $("export-city").onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(layout,null,2)],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download="simroad-city.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $("import-city").onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error("Layout must be smaller than 2 MB");const data=JSON.parse(await file.text());const savedLayout=await request("save_layout",{layout:data});remember();layout=await(await fetch("/api/layout/"+savedLayout.saved)).json();anchor=pick=null;refresh();await saved();}catch(error){showError(error.message);}finally{e.target.value="";}};
 const fitLive=$("fit").onclick;
 $("fit").onclick=()=>{if(!sceneEditor.active)return fitLive();const points=layout.nodes.map(n=>[n.x,n.y]);for(const z of layout.zones)points.push([z.x-z.radius,z.y-z.radius],[z.x+z.radius,z.y+z.radius]);if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);view.scale=Math.min(6,(size.w-100)/Math.max(50,x1-x0),(size.h-100)/Math.max(50,y1-y0));view.x=size.w/2-(x0+x1)/2*view.scale;view.y=size.h/2+(y0+y1)/2*view.scale;draw();};
 const old={down:canvas.onpointerdown,move:canvas.onpointermove,up:canvas.onpointerup,key:canvas.onkeydown};
 const point=e=>{const r=canvas.getBoundingClientRect();return world([e.clientX-r.left,e.clientY-r.top]);};
 canvas.onpointerdown=e=>{if(!sceneEditor.active||tool==="pan")return old.down(e);if(busy)return;canvas.setPointerCapture(e.pointerId);if(tool==="move"){const n=nearest(point(e));if(n){remember();moving=n;}}else click(point(e));};
 canvas.onpointermove=e=>{if(!sceneEditor.active||tool==="pan")return old.move(e);if(moving){const p=point(e);moving.x=Math.round(p[0]/10)*10;moving.y=Math.round(p[1]/10)*10;draw();}};canvas.onpointerup=e=>{if(!sceneEditor.active||tool==="pan")return old.up(e);moving=null;};canvas.onpointercancel=()=>{moving=null;drag=null;};canvas.onkeydown=e=>{old.key(e);if(!sceneEditor.active)return;if(e.key==="Escape"){anchor=null;tool="select";refresh();}if((e.ctrlKey||e.metaKey)&&e.key==="z"){e.preventDefault();$(e.shiftKey?"redo":"undo").click();}if(e.key==="Delete")$("erase").click();};
})();
